-- Generated by `npm run import-desk-decor` from src/data/deskDecorCatalog.json. Don't edit by hand.
-- Decoration prices that Supabase checks purchases and saved desks against (free decorations cost 0).
-- Run in the Supabase SQL editor after 20261117000000_desk_points.sql, and again after every import.

begin;

delete from public.desk_decor_prices where decor_id not in ('white-candle', 'black-candle', 'blue-candle', 'rustic-candle', 'tea-lights', 'teal-candle', 'candle-trio', 'black-coffee', 'cappuccino', 'latte', 'glass-of-tea', 'tea', 'coffee', 'espresso', 'hot-cocoa', 'lavender-tea', 'lavender', 'rose', 'sunflower', 'hibiscus', 'peony', 'pink-daisies', 'tulips', 'bouquet', 'edelweiss', 'autumn-sprig', 'green-sprigs', 'maple-leaves', 'highlighters', 'scissors', 'colored-pencils', 'markers', 'calathea', 'fern', 'pothos');

on conflict (decor_id) do update set price = excluded.price;

commit;
